     1→//! This example shows how to implement a node with a custom EVM that uses a stateful precompile
     2→
     3→#![warn(unused_crate_dependencies)]
     4→
     5→use alloy_evm::{
     6→    eth::EthEvmContext,
     7→    precompiles::{DynPrecompile, Precompile, PrecompileInput, PrecompilesMap},
     8→    revm::{handler::EthPrecompiles, precompile::PrecompileId},
     9→    Evm, EvmFactory,
    10→};
    11→use alloy_genesis::Genesis;
    12→use alloy_primitives::Bytes;
    13→use parking_lot::RwLock;
    14→use reth_ethereum::{
    15→    chainspec::{Chain, ChainSpec},
    16→    evm::{
    17→        primitives::{Database, EvmEnv},
    18→        revm::{
    19→            context::{Context, TxEnv},
    20→            context_interface::result::{EVMError, HaltReason},
    21→            inspector::{Inspector, NoOpInspector},
    22→            interpreter::interpreter::EthInterpreter,
    23→            precompile::PrecompileResult,
    24→            primitives::hardfork::SpecId,
    25→            MainBuilder, MainContext,
    26→        },
    27→    },
    28→    node::{
    29→        api::{FullNodeTypes, NodeTypes},
    30→        builder::{components::ExecutorBuilder, BuilderContext, NodeBuilder},
    31→        core::{args::RpcServerArgs, node_config::NodeConfig},
    32→        evm::EthEvm,
    33→        node::EthereumAddOns,
    34→        EthEvmConfig, EthereumNode,
    35→    },
    36→    tasks::TaskManager,
    37→    EthPrimitives,
    38→};
    39→use reth_tracing::{RethTracer, Tracer};
    40→use schnellru::{ByLength, LruMap};
    41→use std::sync::Arc;
    42→
    43→/// Type alias for the LRU cache used within the [`PrecompileCache`].
    44→type PrecompileLRUCache = LruMap<(Bytes, u64), PrecompileResult>;
    45→
    46→/// A cache for precompile inputs / outputs.
    47→///
    48→/// This cache works with standard precompiles that take input data and gas limit as parameters.
    49→/// The cache key is composed of the input bytes and gas limit, and the cached value is the
    50→/// precompile execution result.
    51→#[derive(Debug)]
    52→pub struct PrecompileCache {
    53→    /// Caches for each precompile input / output.
    54→    cache: PrecompileLRUCache,
    55→}
    56→
    57→/// Custom EVM factory.
    58→#[derive(Debug, Clone)]
    59→#[non_exhaustive]
    60→pub struct MyEvmFactory {
    61→    precompile_cache: Arc<RwLock<PrecompileCache>>,
    62→}
    63→
    64→impl EvmFactory for MyEvmFactory {
    65→    type Evm<DB: Database, I: Inspector<EthEvmContext<DB>, EthInterpreter>> =
    66→        EthEvm<DB, I, PrecompilesMap>;
    67→    type Tx = TxEnv;
    68→    type Error<DBError: core::error::Error + Send + Sync + 'static> = EVMError<DBError>;
    69→    type HaltReason = HaltReason;
    70→    type Context<DB: Database> = EthEvmContext<DB>;
    71→    type Spec = SpecId;
    72→    type Precompiles = PrecompilesMap;
    73→
    74→    fn create_evm<DB: Database>(&self, db: DB, input: EvmEnv) -> Self::Evm<DB, NoOpInspector> {
    75→        let new_cache = self.precompile_cache.clone();
    76→
    77→        let evm = Context::mainnet()
    78→            .with_db(db)
    79→            .with_cfg(input.cfg_env)
    80→            .with_block(input.block_env)
    81→            .build_mainnet_with_inspector(NoOpInspector {})
    82→            .with_precompiles(PrecompilesMap::from_static(EthPrecompiles::default().precompiles));
    83→
    84→        let mut evm = EthEvm::new(evm, false);
    85→
    86→        evm.precompiles_mut().map_precompiles(|_, precompile| {
    87→            WrappedPrecompile::wrap(precompile, new_cache.clone())
    88→        });
    89→
    90→        evm
    91→    }
    92→
    93→    fn create_evm_with_inspector<DB: Database, I: Inspector<Self::Context<DB>, EthInterpreter>>(
    94→        &self,
    95→        db: DB,
    96→        input: EvmEnv,
    97→        inspector: I,
    98→    ) -> Self::Evm<DB, I> {
    99→        EthEvm::new(self.create_evm(db, input).into_inner().with_inspector(inspector), true)
   100→    }
   101→}
   102→
   103→/// A custom precompile that contains the cache and precompile it wraps.
   104→#[derive(Clone)]
   105→pub struct WrappedPrecompile {
   106→    /// The precompile to wrap.
   107→    precompile: DynPrecompile,
   108→    /// The cache to use.
   109→    cache: Arc<RwLock<PrecompileCache>>,
   110→}
   111→
   112→impl WrappedPrecompile {
   113→    fn new(precompile: DynPrecompile, cache: Arc<RwLock<PrecompileCache>>) -> Self {
   114→        Self { precompile, cache }
   115→    }
   116→
   117→    /// Given a [`DynPrecompile`] and cache for a specific precompiles, create a
   118→    /// wrapper that can be used inside Evm.
   119→    fn wrap(precompile: DynPrecompile, cache: Arc<RwLock<PrecompileCache>>) -> DynPrecompile {
   120→        let precompile_id = precompile.precompile_id().clone();
   121→        let wrapped = Self::new(precompile, cache);
   122→        (precompile_id, move |input: PrecompileInput<'_>| -> PrecompileResult {
   123→            wrapped.call(input)
   124→        })
   125→            .into()
   126→    }
   127→}
   128→
   129→impl Precompile for WrappedPrecompile {
   130→    fn precompile_id(&self) -> &PrecompileId {
   131→        self.precompile.precompile_id()
   132→    }
   133→
   134→    fn call(&self, input: PrecompileInput<'_>) -> PrecompileResult {
   135→        let mut cache = self.cache.write();
   136→        let key = (Bytes::copy_from_slice(input.data), input.gas);
   137→
   138→        // get the result if it exists
   139→        if let Some(result) = cache.cache.get(&key) {
   140→            return result.clone()
   141→        }
   142→
   143→        // call the precompile if cache miss
   144→        let output = self.precompile.call(input);
   145→
   146→        // insert the result into the cache
   147→        cache.cache.insert(key, output.clone());
   148→
   149→        output
   150→    }
   151→}
   152→
   153→/// Builds a regular ethereum block executor that uses the custom EVM.
   154→#[derive(Debug, Clone)]
   155→#[non_exhaustive]
   156→pub struct MyExecutorBuilder {
   157→    /// The precompile cache to use for all executors.
   158→    precompile_cache: Arc<RwLock<PrecompileCache>>,
   159→}
   160→
   161→impl Default for MyExecutorBuilder {
   162→    fn default() -> Self {
   163→        let precompile_cache = PrecompileCache {
   164→            cache: LruMap::<(Bytes, u64), PrecompileResult>::new(ByLength::new(100)),
   165→        };
   166→        Self { precompile_cache: Arc::new(RwLock::new(precompile_cache)) }
   167→    }
   168→}
   169→
   170→impl<Node> ExecutorBuilder<Node> for MyExecutorBuilder
   171→where
   172→    Node: FullNodeTypes<Types: NodeTypes<ChainSpec = ChainSpec, Primitives = EthPrimitives>>,
   173→{
   174→    type EVM = EthEvmConfig<ChainSpec, MyEvmFactory>;
   175→
   176→    async fn build_evm(self, ctx: &BuilderContext<Node>) -> eyre::Result<Self::EVM> {
   177→        let evm_config = EthEvmConfig::new_with_evm_factory(
   178→            ctx.chain_spec(),
   179→            MyEvmFactory { precompile_cache: self.precompile_cache.clone() },
   180→        );
   181→        Ok(evm_config)
   182→    }
   183→}
   184→
   185→#[tokio::main]
   186→async fn main() -> eyre::Result<()> {
   187→    let _guard = RethTracer::new().init()?;
   188→
   189→    let tasks = TaskManager::current();
   190→
   191→    // create a custom chain spec
   192→    let spec = ChainSpec::builder()
   193→        .chain(Chain::mainnet())
   194→        .genesis(Genesis::default())
   195→        .london_activated()
   196→        .paris_activated()
   197→        .shanghai_activated()
   198→        .cancun_activated()
   199→        .build();
   200→
   201→    let node_config =
   202→        NodeConfig::test().with_rpc(RpcServerArgs::default().with_http()).with_chain(spec);
   203→
   204→    let handle = NodeBuilder::new(node_config)
   205→        .testing_node(tasks.executor())
   206→        // configure the node with regular ethereum types
   207→        .with_types::<EthereumNode>()
   208→        // use default ethereum components but with our executor
   209→        .with_components(EthereumNode::components().executor(MyExecutorBuilder::default()))
   210→        .with_add_ons(EthereumAddOns::default())
   211→        .launch()
   212→        .await
   213→        .unwrap();
   214→
   215→    println!("Node started");
   216→
   217→    handle.node_exit_future.await
   218→}
