  1120→    /// Reveals either a node or its hash placeholder based on the provided child data.
  1121→    ///
  1122→    /// When traversing the trie, we often encounter references to child nodes that
  1123→    /// are either directly embedded or represented by their hash. This method
  1124→    /// handles both cases:
  1125→    ///
  1126→    /// 1. If the child data represents a hash (32+1=33 bytes), store it as a hash node
  1127→    /// 2. Otherwise, decode the data as a [`TrieNode`] and recursively reveal it using
  1128→    ///    `reveal_node`
  1129→    ///
  1130→    /// # Returns
  1131→    ///
  1132→    /// Returns `Ok(())` if successful, or an error if the node cannot be revealed.
  1133→    ///
  1134→    /// # Error Handling
  1135→    ///
  1136→    /// Will error if there's a conflict between a new hash node and an existing one
  1137→    /// at the same path
  1138→    fn reveal_node_or_hash(&mut self, path: Nibbles, child: &[u8]) -> SparseTrieResult<()> {
  1139→        if child.len() == B256::len_bytes() + 1 {
  1140→            let hash = B256::from_slice(&child[1..]);
  1141→            match self.nodes.entry(path) {
  1142→                Entry::Occupied(entry) => match entry.get() {
  1143→                    // Hash node with a different hash can't be handled.
  1144→                    SparseNode::Hash(previous_hash) if previous_hash != &hash => {
  1145→                        return Err(SparseTrieErrorKind::Reveal {
  1146→                            path: *entry.key(),
  1147→                            node: Box::new(SparseNode::Hash(hash)),
  1148→                        }
  1149→                        .into())
  1150→                    }
  1151→                    _ => {}
  1152→                },
  1153→                Entry::Vacant(entry) => {
  1154→                    entry.insert(SparseNode::Hash(hash));
  1155→                }
  1156→            }
  1157→            return Ok(())
  1158→        }
  1159→
  1160→        self.reveal_node(path, TrieNode::decode(&mut &child[..])?, TrieMasks::none())
  1161→    }
