  1163→    /// Traverse the trie from the root down to the leaf at the given path,
  1164→    /// removing and collecting all nodes along that path.
  1165→    ///
  1166→    /// This helper function is used during leaf removal to extract the nodes of the trie
  1167→    /// that will be affected by the deletion. These nodes are then re-inserted and modified
  1168→    /// as needed (collapsing extension nodes etc) given that the leaf has now been removed.
  1169→    ///
  1170→    /// # Returns
  1171→    ///
  1172→    /// Returns a vector of [`RemovedSparseNode`] representing the nodes removed during the
  1173→    /// traversal.
  1174→    ///
  1175→    /// # Errors
  1176→    ///
  1177→    /// Returns an error if a blinded node or an empty node is encountered unexpectedly,
  1178→    /// as these prevent proper removal of the leaf.
  1179→    fn take_nodes_for_path(&mut self, path: &Nibbles) -> SparseTrieResult<Vec<RemovedSparseNode>> {
  1180→        let mut current = Nibbles::default(); // Start traversal from the root
  1181→        let mut nodes = Vec::new(); // Collect traversed nodes
  1182→
  1183→        while let Some(node) = self.nodes.remove(&current) {
  1184→            match &node {
  1185→                SparseNode::Empty => return Err(SparseTrieErrorKind::Blind.into()),
  1186→                &SparseNode::Hash(hash) => {
  1187→                    return Err(SparseTrieErrorKind::BlindedNode { path: current, hash }.into())
  1188→                }
  1189→                SparseNode::Leaf { key: _key, .. } => {
  1190→                    // Leaf node is always the one that we're deleting, and no other leaf nodes can
  1191→                    // be found during traversal.
  1192→
  1193→                    #[cfg(debug_assertions)]
  1194→                    {
  1195→                        let mut current = current;
  1196→                        current.extend(_key);
  1197→                        assert_eq!(&current, path);
  1198→                    }
  1199→
  1200→                    nodes.push(RemovedSparseNode {
  1201→                        path: current,
  1202→                        node,
  1203→                        unset_branch_nibble: None,
  1204→                    });
  1205→                    break
  1206→                }
  1207→                SparseNode::Extension { key, .. } => {
  1208→                    #[cfg(debug_assertions)]
  1209→                    {
  1210→                        let mut current = current;
  1211→                        current.extend(key);
  1212→                        assert!(
  1213→                            path.starts_with(&current),
  1214→                            "path: {path:?}, current: {current:?}, key: {key:?}",
  1215→                        );
  1216→                    }
  1217→
  1218→                    let path = current;
  1219→                    current.extend(key);

