   491→/// An error due to invalid transaction.
   492→///
   493→/// The only reason this exists is to maintain compatibility with other clients de-facto standard
   494→/// error messages.
   495→///
   496→/// These error variants can be thrown when the transaction is checked prior to execution.
   497→///
   498→/// These variants also cover all errors that can be thrown by revm.
   499→///
   500→/// ## Nomenclature
   501→///
   502→/// This type is explicitly modeled after geth's error variants and uses
   503→///   `fee cap` for `max_fee_per_gas`
   504→///   `tip` for `max_priority_fee_per_gas`
   505→#[derive(thiserror::Error, Debug)]
   506→pub enum RpcInvalidTransactionError {
   507→    /// returned if the nonce of a transaction is lower than the one present in the local chain.
   508→    #[error("nonce too low: next nonce {state}, tx nonce {tx}")]
   509→    NonceTooLow {
   510→        /// The nonce of the transaction.
   511→        tx: u64,
   512→        /// The current state of the nonce in the local chain.
   513→        state: u64,
   514→    },
   515→    /// returned if the nonce of a transaction is higher than the next one expected based on the
   516→    /// local chain.
   517→    #[error("nonce too high")]
   518→    NonceTooHigh,
   519→    /// Returned if the nonce of a transaction is too high
   520→    /// Incrementing the nonce would lead to invalid state (overflow)
   521→    #[error("nonce has max value")]
   522→    NonceMaxValue,
   523→    /// thrown if the transaction sender doesn't have enough funds for a transfer
   524→    #[error("insufficient funds for transfer")]
   525→    InsufficientFundsForTransfer,
   526→    /// thrown if creation transaction provides the init code bigger than init code size limit.
   527→    #[error("max initcode size exceeded")]
   528→    MaxInitCodeSizeExceeded,
   529→    /// Represents the inability to cover max fee + value (account balance too low).
   530→    #[error("insufficient funds for gas * price + value: have {balance} want {cost}")]
   531→    InsufficientFunds {
   532→        /// Transaction cost.
   533→        cost: U256,
   534→        /// Current balance of transaction sender.
   535→        balance: U256,
   536→    },
   537→    /// This is similar to [`Self::InsufficientFunds`] but with a different error message and
   538→    /// exists for compatibility reasons.
   539→    ///
   540→    /// This error is used in `eth_estimateCall` when the highest available gas limit, capped with
   541→    /// the allowance of the caller is too low: [`Self::GasTooLow`].
   542→    #[error("gas required exceeds allowance ({gas_limit})")]
   543→    GasRequiredExceedsAllowance {
   544→        /// The gas limit the transaction was executed with.
   545→        gas_limit: u64,
   546→    },
   547→    /// Thrown when calculating gas usage
   548→    #[error("gas uint64 overflow")]
   549→    GasUintOverflow,
   550→    /// Thrown if the transaction is specified to use less gas than required to start the
   551→    /// invocation.
   552→    #[error("intrinsic gas too low")]
   553→    GasTooLow,
   554→    /// Thrown if the transaction gas exceeds the limit
   555→    #[error("intrinsic gas too high")]
   556→    GasTooHigh,
   557→    /// Thrown if the transaction gas limit exceeds the maximum
   558→    #[error("gas limit too high")]
   559→    GasLimitTooHigh,
   560→    /// Thrown if a transaction is not supported in the current network configuration.
   561→    #[error("transaction type not supported")]
   562→    TxTypeNotSupported,
   563→    /// Thrown to ensure no one is able to specify a transaction with a tip higher than the total
   564→    /// fee cap.
   565→    #[error("max priority fee per gas higher than max fee per gas")]
   566→    TipAboveFeeCap,
   567→    /// A sanity error to avoid huge numbers specified in the tip field.
   568→    #[error("max priority fee per gas higher than 2^256-1")]
   569→    TipVeryHigh,
   570→    /// A sanity error to avoid huge numbers specified in the fee cap field.
   571→    #[error("max fee per gas higher than 2^256-1")]
   572→    FeeCapVeryHigh,
   573→    /// Thrown post London if the transaction's fee is less than the base fee of the block
   574→    #[error("max fee per gas less than block base fee")]
   575→    FeeCapTooLow,
   576→    /// Thrown if the sender of a transaction is a contract.
   577→    #[error("sender is not an EOA")]
   578→    SenderNoEOA,
   579→    /// Gas limit was exceeded during execution.
   580→    /// Contains the gas limit.
   581→    #[error("out of gas: gas required exceeds: {0}")]
   582→    BasicOutOfGas(u64),
   583→    /// Gas limit was exceeded during memory expansion.
   584→    /// Contains the gas limit.
   585→    #[error("out of gas: gas exhausted during memory expansion: {0}")]
   586→    MemoryOutOfGas(u64),
   587→    /// Gas limit was exceeded during precompile execution.
   588→    /// Contains the gas limit.
   589→    #[error("out of gas: gas exhausted during precompiled contract execution: {0}")]
   590→    PrecompileOutOfGas(u64),
   591→    /// An operand to an opcode was invalid or out of range.
   592→    /// Contains the gas limit.
   593→    #[error("out of gas: invalid operand to an opcode: {0}")]
   594→    InvalidOperandOutOfGas(u64),
   595→    /// Thrown if executing a transaction failed during estimate/call
   596→    #[error(transparent)]
   597→    Revert(RevertError),
   598→    /// Unspecific EVM halt error.
   599→    #[error("EVM error: {0:?}")]
   600→    EvmHalt(HaltReason),
   601→    /// Invalid chain id set for the transaction.
   602→    #[error("invalid chain ID")]
   603→    InvalidChainId,
   604→    /// The transaction is before Spurious Dragon and has a chain ID
   605→    #[error("transactions before Spurious Dragon should not have a chain ID")]
   606→    OldLegacyChainId,
   607→    /// The transitions is before Berlin and has access list
   608→    #[error("transactions before Berlin should not have access list")]
   609→    AccessListNotSupported,
   610→    /// `max_fee_per_blob_gas` is not supported for blocks before the Cancun hardfork.
   611→    #[error("max_fee_per_blob_gas is not supported for blocks before the Cancun hardfork")]
   612→    MaxFeePerBlobGasNotSupported,
   613→    /// `blob_hashes`/`blob_versioned_hashes` is not supported for blocks before the Cancun
   614→    /// hardfork.
   615→    #[error("blob_versioned_hashes is not supported for blocks before the Cancun hardfork")]
   616→    BlobVersionedHashesNotSupported,
   617→    /// Block `blob_base_fee` is greater than tx-specified `max_fee_per_blob_gas` after Cancun.
   618→    #[error("max fee per blob gas less than block blob gas fee")]
   619→    BlobFeeCapTooLow,
   620→    /// Blob transaction has a versioned hash with an invalid blob
   621→    #[error("blob hash version mismatch")]
   622→    BlobHashVersionMismatch,
   623→    /// Blob transaction has no versioned hashes
   624→    #[error("blob transaction missing blob hashes")]
   625→    BlobTransactionMissingBlobHashes,
   626→    /// Blob transaction has too many blobs
   627→    #[error("blob transaction exceeds max blobs per block; got {have}")]
   628→    TooManyBlobs {
   629→        /// The number of blobs in the transaction.
   630→        have: usize,
   631→    },
   632→    /// Blob transaction is a create transaction
   633→    #[error("blob transaction is a create transaction")]
   634→    BlobTransactionIsCreate,
   635→    /// EIP-7702 is not enabled.
   636→    #[error("EIP-7702 authorization list not supported")]
   637→    AuthorizationListNotSupported,
   638→    /// EIP-7702 transaction has invalid fields set.
   639→    #[error("EIP-7702 authorization list has invalid fields")]
   640→    AuthorizationListInvalidFields,
   641→    /// Transaction priority fee is below the minimum required priority fee.
   642→    #[error("transaction priority fee below minimum required priority fee {minimum_priority_fee}")]
   643→    PriorityFeeBelowMinimum {
   644→        /// Minimum required priority fee.
   645→        minimum_priority_fee: u128,
   646→    },
   647→    /// Any other error
   648→    #[error("{0}")]
   649→    Other(Box<dyn ToRpcError>),
   650→}
   651→
   652→impl RpcInvalidTransactionError {
   653→    /// crates a new [`RpcInvalidTransactionError::Other`] variant.
   654→    pub fn other<E: ToRpcError>(err: E) -> Self {
   655→        Self::Other(Box::new(err))
   656→    }
   657→
   658→    /// Returns the rpc error code for this error.
   659→    pub const fn error_code(&self) -> i32 {
   660→        match self {
   661→            Self::InvalidChainId |
   662→            Self::GasTooLow |
   663→            Self::GasTooHigh |
   664→            Self::GasRequiredExceedsAllowance { .. } |
   665→            Self::NonceTooLow { .. } |
   666→            Self::NonceTooHigh { .. } |
   667→            Self::FeeCapTooLow |
   668→            Self::FeeCapVeryHigh => EthRpcErrorCode::InvalidInput.code(),
   669→            Self::Revert(_) => EthRpcErrorCode::ExecutionError.code(),
   670→            _ => EthRpcErrorCode::TransactionRejected.code(),
   671→        }
   672→    }
   673→
   674→    /// Converts the halt error
   675→    ///
   676→    /// Takes the configured gas limit of the transaction which is attached to the error
   677→    pub const fn halt(reason: HaltReason, gas_limit: u64) -> Self {
   678→        match reason {
   679→            HaltReason::OutOfGas(err) => Self::out_of_gas(err, gas_limit),
   680→            HaltReason::NonceOverflow => Self::NonceMaxValue,
   681→            err => Self::EvmHalt(err),
   682→        }
   683→    }
   684→
   685→    /// Converts the out of gas error
   686→    pub const fn out_of_gas(reason: OutOfGasError, gas_limit: u64) -> Self {
   687→        match reason {
   688→            OutOfGasError::Basic | OutOfGasError::ReentrancySentry => {
   689→                Self::BasicOutOfGas(gas_limit)
   690→            }
   691→            OutOfGasError::Memory | OutOfGasError::MemoryLimit => Self::MemoryOutOfGas(gas_limit),
   692→            OutOfGasError::Precompile => Self::PrecompileOutOfGas(gas_limit),
   693→            OutOfGasError::InvalidOperand => Self::InvalidOperandOutOfGas(gas_limit),
   694→        }
   695→    }
   696→
   697→    /// Converts this error into the rpc error object.
   698→    pub fn into_rpc_err(self) -> jsonrpsee_types::error::ErrorObject<'static> {
   699→        self.into()
   700→    }
   701→}
   702→
   703→impl From<RpcInvalidTransactionError> for jsonrpsee_types::error::ErrorObject<'static> {
   704→    fn from(err: RpcInvalidTransactionError) -> Self {
   705→        match err {
   706→            RpcInvalidTransactionError::Revert(revert) => {
   707→                // include out data if some
   708→                rpc_err(
   709→                    revert.error_code(),
   710→                    revert.to_string(),
   711→                    revert.output.as_ref().map(|out| out.as_ref()),
   712→                )
   713→            }
   714→            RpcInvalidTransactionError::Other(err) => err.to_rpc_error(),
   715→            err => rpc_err(err.error_code(), err.to_string(), None),
   716→        }
   717→    }
   718→}
   719→
   720→impl From<InvalidTransaction> for RpcInvalidTransactionError {
   721→    fn from(err: InvalidTransaction) -> Self {
   722→        match err {
   723→            InvalidTransaction::InvalidChainId | InvalidTransaction::MissingChainId => {
   724→                Self::InvalidChainId
   725→            }
   726→            InvalidTransaction::PriorityFeeGreaterThanMaxFee => Self::TipAboveFeeCap,
   727→            InvalidTransaction::GasPriceLessThanBasefee => Self::FeeCapTooLow,
   728→            InvalidTransaction::CallerGasLimitMoreThanBlock |
   729→            InvalidTransaction::TxGasLimitGreaterThanCap { .. } => {
   730→                // tx.gas > block.gas_limit
   731→                Self::GasTooHigh
   732→            }
   733→            InvalidTransaction::CallGasCostMoreThanGasLimit { .. } => {
   734→                // tx.gas < cost
   735→                Self::GasTooLow
   736→            }
   737→            InvalidTransaction::GasFloorMoreThanGasLimit { .. } => {
   738→                // Post prague EIP-7623 tx floor calldata gas cost > tx.gas_limit
   739→                // where floor gas is the minimum amount of gas that will be spent
   740→                // In other words, the tx's gas limit is lower that the minimum gas requirements of
   741→                // the tx's calldata
   742→                Self::GasTooLow
   743→            }
   744→            InvalidTransaction::RejectCallerWithCode => Self::SenderNoEOA,
   745→            InvalidTransaction::LackOfFundForMaxFee { fee, balance } => {
   746→                Self::InsufficientFunds { cost: *fee, balance: *balance }
   747→            }
   748→            InvalidTransaction::OverflowPaymentInTransaction => Self::GasUintOverflow,
   749→            InvalidTransaction::NonceOverflowInTransaction => Self::NonceMaxValue,
   750→            InvalidTransaction::CreateInitCodeSizeLimit => Self::MaxInitCodeSizeExceeded,
   751→            InvalidTransaction::NonceTooHigh { .. } => Self::NonceTooHigh,
   752→            InvalidTransaction::NonceTooLow { tx, state } => Self::NonceTooLow { tx, state },
   753→            InvalidTransaction::AccessListNotSupported => Self::AccessListNotSupported,
   754→            InvalidTransaction::MaxFeePerBlobGasNotSupported => Self::MaxFeePerBlobGasNotSupported,
   755→            InvalidTransaction::BlobVersionedHashesNotSupported => {
   756→                Self::BlobVersionedHashesNotSupported
   757→            }
   758→            InvalidTransaction::BlobGasPriceGreaterThanMax => Self::BlobFeeCapTooLow,
   759→            InvalidTransaction::EmptyBlobs => Self::BlobTransactionMissingBlobHashes,
   760→            InvalidTransaction::BlobVersionNotSupported => Self::BlobHashVersionMismatch,
   761→            InvalidTransaction::TooManyBlobs { have, .. } => Self::TooManyBlobs { have },
   762→            InvalidTransaction::BlobCreateTransaction => Self::BlobTransactionIsCreate,
   763→            InvalidTransaction::AuthorizationListNotSupported => {
   764→                Self::AuthorizationListNotSupported
   765→            }
   766→            InvalidTransaction::AuthorizationListInvalidFields |
   767→            InvalidTransaction::EmptyAuthorizationList => Self::AuthorizationListInvalidFields,
   768→            InvalidTransaction::Eip2930NotSupported |
   769→            InvalidTransaction::Eip1559NotSupported |
   770→            InvalidTransaction::Eip4844NotSupported |
   771→            InvalidTransaction::Eip7702NotSupported |
   772→            InvalidTransaction::Eip7873NotSupported => Self::TxTypeNotSupported,
   773→            InvalidTransaction::Eip7873MissingTarget => {
   774→                Self::other(internal_rpc_err(err.to_string()))
   775→            }
   776→        }
   777→    }
   778→}
   779→
   780→impl From<InvalidTransactionError> for RpcInvalidTransactionError {
   781→    fn from(err: InvalidTransactionError) -> Self {
   782→        use InvalidTransactionError;
   783→        // This conversion is used to convert any transaction errors that could occur inside the
   784→        // txpool (e.g. `eth_sendRawTransaction`) to their corresponding RPC
   785→        match err {
   786→            InvalidTransactionError::InsufficientFunds(res) => {
   787→                Self::InsufficientFunds { cost: res.expected, balance: res.got }
   788→            }
   789→            InvalidTransactionError::NonceNotConsistent { tx, state } => {
   790→                Self::NonceTooLow { tx, state }
   791→            }
   792→            InvalidTransactionError::OldLegacyChainId => {
   793→                // Note: this should be unreachable since Spurious Dragon now enabled
   794→                Self::OldLegacyChainId
   795→            }
   796→            InvalidTransactionError::ChainIdMismatch => Self::InvalidChainId,
   797→            InvalidTransactionError::Eip2930Disabled |
   798→            InvalidTransactionError::Eip1559Disabled |
   799→            InvalidTransactionError::Eip4844Disabled |
   800→            InvalidTransactionError::Eip7702Disabled |
   801→            InvalidTransactionError::TxTypeNotSupported => Self::TxTypeNotSupported,
   802→            InvalidTransactionError::GasUintOverflow => Self::GasUintOverflow,
   803→            InvalidTransactionError::GasTooLow => Self::GasTooLow,
   804→            InvalidTransactionError::GasTooHigh => Self::GasTooHigh,
   805→            InvalidTransactionError::TipAboveFeeCap => Self::TipAboveFeeCap,
   806→            InvalidTransactionError::FeeCapTooLow => Self::FeeCapTooLow,
   807→            InvalidTransactionError::SignerAccountHasBytecode => Self::SenderNoEOA,
   808→            InvalidTransactionError::GasLimitTooHigh => Self::GasLimitTooHigh,
   809→        }
   810→    }
   811→}
