   813→/// Represents a reverted transaction and its output data.
   814→///
   815→/// Displays "execution reverted(: reason)?" if the reason is a string.
   816→#[derive(Debug, Clone, thiserror::Error)]
   817→pub struct RevertError {
   818→    /// The transaction output data
   819→    ///
   820→    /// Note: this is `None` if output was empty
   821→    output: Option<Bytes>,
   822→}
   823→
   824→// === impl RevertError ==
   825→
   826→impl RevertError {
   827→    /// Wraps the output bytes
   828→    ///
   829→    /// Note: this is intended to wrap an revm output
   830→    pub fn new(output: Bytes) -> Self {
   831→        if output.is_empty() {
   832→            Self { output: None }
   833→        } else {
   834→            Self { output: Some(output) }
   835→        }
   836→    }
   837→
   838→    /// Returns error code to return for this error.
   839→    pub const fn error_code(&self) -> i32 {
   840→        EthRpcErrorCode::ExecutionError.code()
   841→    }
   842→}
   843→
   844→impl std::fmt::Display for RevertError {
   845→    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
   846→        f.write_str("execution reverted")?;
   847→        if let Some(reason) = self.output.as_ref().and_then(|out| RevertReason::decode(out)) {
   848→            let error = reason.to_string();
   849→            let mut error = error.as_str();
   850→            if matches!(reason, RevertReason::ContractError(ContractError::Revert(_))) {
   851→                // we strip redundant `revert: ` prefix from the revert reason
   852→                error = error.trim_start_matches("revert: ");
   853→            }
   854→            write!(f, ": {error}")?;
   855→        }
   856→        Ok(())
   857→    }
   858→}
