   928→            RpcPoolError::Invalid(err) => err.into(),
   929→            RpcPoolError::TxPoolOverflow => {
   930→                rpc_error_with_code(EthRpcErrorCode::TransactionRejected.code(), error.to_string())
   931→            }
   932→            RpcPoolError::AlreadyKnown |
   933→            RpcPoolError::InvalidSender |
   934→            RpcPoolError::Underpriced |
   935→            RpcPoolError::ReplaceUnderpriced |
   936→            RpcPoolError::ExceedsGasLimit |
