   939→            RpcPoolError::NegativeValue |
   940→            RpcPoolError::OversizedData |
   941→            RpcPoolError::ExceedsMaxInitCodeSize |
   942→            RpcPoolError::PoolTransactionError(_) |
   943→            RpcPoolError::Eip4844(_) |
   944→            RpcPoolError::Eip7702(_) |
   945→            RpcPoolError::AddressAlreadyReserved => {
   946→                rpc_error_with_code(EthRpcErrorCode::InvalidInput.code(), error.to_string())
   947→            }
   948→            RpcPoolError::Other(other) => internal_rpc_err(other.to_string()),
