  1030→/// Converts the evm [`ExecutionResult`] into a result where `Ok` variant is the output bytes if it
  1031→/// is [`ExecutionResult::Success`].
  1032→pub fn ensure_success<Halt, Error: FromEvmHalt<Halt> + FromEthApiError>(
  1033→    result: ExecutionResult<Halt>,
  1034→) -> Result<Bytes, Error> {
  1035→    match result {
  1036→        ExecutionResult::Success { output, .. } => Ok(output.into_data()),
  1037→        ExecutionResult::Revert { output, .. } => {
  1038→            Err(Error::from_eth_err(RpcInvalidTransactionError::Revert(RevertError::new(output))))
  1039→        }
  1040→        ExecutionResult::Halt { reason, gas_used } => Err(Error::from_evm_halt(reason, gas_used)),
  1041→    }
  1042→}
